INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-1', 'Free In-Home Measurement / Site Visit', 'free-in-home-measurement', 'Our technical specialists visit your space with laser precision tools to record exact millimeter dimensions.', 'Ensure flawless drape drops and window fit with our complimentary on-site measurement service. Our specialists check wall structural integrity, track clearances, and drop heights so your custom furnishings fit immaculately.', '/images/services/free-home-measurement.jpg', 'Ruler', '["Laser accurate dimensions","Zero obligation assessment","On-site technical consultation"]', 1, 1, 0);
INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-2', 'Doorstep Fabric / Sample Demo', 'doorstep-fabric-demo', 'Experience luxury textile swatches, wooden finishes, and wallpapers directly in your home’s natural lighting.', 'Lighting alters colors dramatically. Our stylists bring curated fabric swatches, drape samples, and tactile catalogues directly to your doorstep so you can assess textures alongside your existing furniture and ambient light.', '/images/services/fabric-samples-at-home.jpg', 'Sparkles', '["500+ curated swatches","Test in your home lighting","Stylist guidance"]', 1, 1, 1);
INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-3', 'Custom Tailoring & Stitching', 'custom-tailoring-and-stitching', 'Master atelier stitching for custom headers, double-pinch pleats, motorized hems, and bespoke upholstery.', 'Every curtain drape, cushion accent, and sofa slipcover is handcrafted by experienced artisans using high-grade German interlinings, blind stitch hemming, and calibrated fullness ratios for perfect waterfall draping.', '/images/services/custom-stitching.jpg', 'Scissors', '["Master artisan ateliers","French & Pinch pleat specialists","Weighted drapery hems"]', 0, 1, 2);
INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-4', 'Professional Installation', 'professional-installation', 'Dust-free, discreet installation of motorized tracks, wooden flooring, blinds, and heavy architectural drapes.', 'Trained technical crews ensure level mounting, sturdy concealed anchor points, and seamless track alignment using dust-containment drilling equipment to keep your home pristine.', '/images/services/professional-installation.jpg', 'Hammer', '["Dust-free drilling equipment","Concealed architectural hardware","Post-install steaming"]', 1, 1, 3);
INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-5', 'Motorization / Smart Home Setup', 'motorization-smart-home', 'Whisper-quiet motorized tracks and automated blinds integrated with Somfy, Alexa, Google Home & Tuya.', 'Automate your drapery and roller shades with ultra-quiet motors. Schedule automatic sunrise opening, sunset privacy closing, and voice-command activation seamlessly paired with your smart home ecosystem.', '/images/services/smart-blinds-setup.jpg', 'Cpu', '["Somfy & smart ecosystem integration","Ultra-quiet motors (<35dB)","App & voice control scheduling"]', 0, 1, 4);
INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-6', 'NRI Remote Home Styling', 'nri-remote-home-styling', 'Turnkey interior furnishing service for homeowners living abroad, managed via video walkthroughs.', 'Furnishing a home in India while residing overseas? We coordinate complete site measurements, digital moodboard curations, video-call textile selections, and turnkey delivery with verified milestone updates.', '/images/services/remote-home-styling.jpg', 'Globe', '["Dedicated relationship manager","Live video fabric walkthroughs","Turnkey handover before your arrival"]', 0, 1, 5);
INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-7', 'Corporate / Institutional Furnishings', 'corporate-institutional-furnishings', 'Flame-retardant curtains, heavy-duty acoustic carpet tiles, and motorized conference blinds for commercial spaces.', 'Engineered commercial grade solutions for hotels, corporate headquarters, luxury clinics, and executive suites. All commercial textiles carry flame retardancy (FR) and high Martindale abrasion certifications.', '/images/hero/living_room.jpg', 'Building2', '["FR Certified textiles","Heavy commercial Martindale ratings","Bulk project execution"]', 0, 1, 6);
INSERT OR REPLACE INTO services (id, name, slug, short_desc, full_desc, image, icon_name, highlights, requires_site_visit, active, display_order) VALUES ('srv-8', 'Warranty & After-Sales Support', 'warranty-after-sales', 'Comprehensive warranty coverage on stitching, motor mechanisms, and on-demand steam refurbishment.', 'Our relationship extends far beyond initial fitting. Enjoy peace of mind with multi-year warranty coverage on motor systems, track repairs, and seasonal dry cleaning or re-hanging assistance.', '/images/services/warranty-after-sales.jpg', 'ShieldCheck', '["Up to 5-year motor warranty","Lifetime track alignment guarantee","Dedicated maintenance support"]', 0, 1, 7);
INSERT OR REPLACE INTO cms_content (id, section_key, title, subtitle, content, image_url, secondary_image_url) VALUES ('cms-home_hero', 'home_hero', 'Beautiful Furnishings for Your Home', 'Curtains, blinds, wallpapers, rugs, flooring and more for your home.', '{"eyebrow":"ZAIRA FURNISHING","primary_cta_text":"Shop Now","primary_cta_link":"/products","secondary_cta_text":"Book a Free Visit","secondary_cta_link":"/services"}', '/images/hero/living_room.jpg', NULL);
INSERT OR REPLACE INTO cms_content (id, section_key, title, subtitle, content, image_url, secondary_image_url) VALUES ('cms-home_featured_furnishings', 'home_featured_furnishings', 'Featured Furnishings', 'Explore selected furnishings from Zaira.', '{"featured_slugs":["blackout-curtains","roma-textured-boucle-upholstery","roller-blinds","solis-hand-tufted-wool-silk-rug","monaco-crush-resistant-matte-velvet"]}', NULL, NULL);
INSERT OR REPLACE INTO cms_content (id, section_key, title, subtitle, content, image_url, secondary_image_url) VALUES ('cms-home_brand_story', 'home_brand_story', 'About Zaira Furnishing', 'Furnishings & Services', '{"paragraph1":"Zaira Furnishing offers a wide range of furnishings and home decor for different spaces in your home.","paragraph2":"From curtains, blinds and sofa fabrics to wallpapers, rugs, flooring, mattresses, bed linen, cushions, dining products and home decor, we help you find furnishings that suit your space.","paragraph3":"Our services include home measurement, fabric and sample visits, custom stitching, professional installation, smart-home setup, remote home styling, commercial furnishing and after-sales support.","cta_text":"Learn More","cta_link":"/about"}', '/images/about/about-main-living.jpg', '/images/about/about-tv-unit.jpg');
INSERT OR REPLACE INTO cms_content (id, section_key, title, subtitle, content, image_url, secondary_image_url) VALUES ('cms-home_showroom_contact', 'home_showroom_contact', 'Visit the Zaira Showroom', 'See fabrics, furnishings and finishes in person, and discuss your requirements with our team.', '{"eyebrow":"VISIT THE SHOWROOM","address":"Rd Number 5, Kyetian Goud Nilayam, Alkapur Twp, Puppalguda, Hyderabad, Telangana 500089","phone":"07947415666","email":"concierge@zairafurnishing.com","hours":"Mon–Sat 10:30 AM–8:30 PM · Sunday by appointment","maps_query":"https://www.google.com/maps/search/?api=1&query=Zaira+Furnishing,+Rd+Number+5,+Kyetian+Goud+Nilayam,+Alkapur+Twp,+Puppalguda,+Hyderabad,+Telangana+500089"}', '/images/hero/living_room.jpg', NULL);
INSERT OR REPLACE INTO cms_content (id, section_key, title, subtitle, content, image_url, secondary_image_url) VALUES ('cms-site_footer', 'site_footer', 'Zaira Furnishing', 'Curtains, blinds, fabrics and furnishings for thoughtfully designed spaces.', '{"copyright":"© 2026 Zaira Furnishing. All rights reserved.","address":"Rd Number 5, Kyetian Goud Nilayam, Alkapur Twp, Puppalguda, Hyderabad, Telangana 500089","phone":"07947415666","email":"concierge@zairafurnishing.com","hours":"Mon–Sat 10:30 AM–8:30 PM\nSunday by appointment"}', NULL, NULL);
